/**
 * Messages, cut 10 (photos saved on arrival): which photos the file agent copies to their job's Drive folder now. A job
 * saves its photos only once the office ticks *Save every photo on this job to Drive as it comes in* (the prototype's
 * `quo-messages-mockup.html` draft 9, on branch spike/gc-mode); the tick starts off on every job, like every other switch
 * (the lead, 2026-10-13). From then on, every photo that comes in on a line tied to that job is copied, even one whose
 * line was tied after it arrived. The sweep that does it reads this every few minutes, so a failed copy is tried again.
 */
import { fileKindOf } from '../documents/jobFiles.ts'

/** The most photos one run of the sweep copies; the rest wait for the next run. */
export const PHOTO_SAVE_BATCH = 20

/** A job, as the spine ties a line: a bid, a GC project or a Pipeline job. */
export interface PhotoJobRef {
  bid_id: string | null
  project_id: string | null
  jobs_ledger_id: string | null
}

/** A file on a line, as `message_attachments` keeps it, with the line it came on. */
export interface PhotoRow {
  id: string
  kind: string
  name: string
  mime: string | null
  /** Our copy in the message-attachments bucket; null when it was left where it came from. */
  bucket_path: string | null
  /** Where it already is in Drive, by a save or an earlier run. */
  drive_file_id: string | null
  /** How a file on a line we sent went; null on a line that came in. */
  sent_as: string | null
  line: PhotoJobRef & { direction: string; at: string }
}

/** A job's tick: on since when, or null when it is off. */
export interface PhotoSwitch extends PhotoJobRef {
  on_since: string | null
}

/** Why a file is not copied now. */
export type NotSavedWhy = 'notAPhoto' | 'notKept' | 'inDrive' | 'ours' | 'noJob' | 'switchOff' | 'before'

/** One key for a job, the way the save picks it: a GC project first, then a bid, then a Pipeline job. */
export function photoJobKey(job: PhotoJobRef): string | null {
  if (job.project_id) return `project:${job.project_id}`
  if (job.bid_id) return `bid:${job.bid_id}`
  if (job.jobs_ledger_id) return `pipeline:${job.jobs_ledger_id}`
  return null
}

/** A picture, by its type, or by its name's ending when the type says nothing. */
export function isPhoto(row: Pick<PhotoRow, 'kind' | 'mime' | 'name'>): boolean {
  return row.kind === 'file' && fileKindOf(row.mime ?? '', row.name) === 'image'
}

/** Why this file is not copied now, or null when it is. */
export function notSavedWhy(row: PhotoRow, switches: ReadonlyMap<string, string | null>): NotSavedWhy | null {
  if (!isPhoto(row)) return 'notAPhoto'
  if (!row.bucket_path) return 'notKept'
  if (row.drive_file_id) return 'inDrive'
  if (row.sent_as !== null || row.line.direction !== 'in') return 'ours'
  const key = photoJobKey(row.line)
  if (!key) return 'noJob'
  const since = switches.get(key) ?? null
  if (!since) return 'switchOff'
  if (Date.parse(row.line.at) < Date.parse(since)) return 'before'
  return null
}

/** Each job's tick by its key, for `notSavedWhy`. */
export function switchesByJob(switches: readonly PhotoSwitch[]): Map<string, string | null> {
  const out = new Map<string, string | null>()
  for (const s of switches) {
    const key = photoJobKey(s)
    if (key) out.set(key, s.on_since)
  }
  return out
}

/** The photos to copy now, oldest first, at most `max` of them. */
export function photosToSave(rows: readonly PhotoRow[], switches: readonly PhotoSwitch[], max = PHOTO_SAVE_BATCH): PhotoRow[] {
  const on = switchesByJob(switches)
  return rows
    .filter((r) => notSavedWhy(r, on) === null)
    .sort((a, b) => Date.parse(a.line.at) - Date.parse(b.line.at) || a.id.localeCompare(b.id))
    .slice(0, Math.max(0, max))
}
